#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = '/bench/repo';

sub strip_comments {
    my ($text) = @_;
    $text =~ s{/\*.*?\*/}{}gs;
    my @lines;
    for my $line (split /\n/, $text) {
        $line =~ s{//.*$}{};
        push @lines, $line;
    }
    return join("\n", @lines);
}

sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return;
    my $raw = do { local $/; <$fh> };
    close $fh;
    my $text = strip_comments($raw);

    my $pkg;
    if ($text =~ /^package\s+(\w+)/m) {
        $pkg = $1;
    }

    my @imports;
    # import block
    while ($text =~ /import\s*\((.*?)\)/gs) {
        my $block = $1;
        for my $imp ($block =~ /(?:"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
            # handled below per line
        }
        for my $line (split /\n/, $block) {
            $line =~ s/^\s+|\s+$//g;
            next if $line eq '' || $line =~ /^_/;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                push @imports, { alias => $1, path => $2 };
            } elsif ($line =~ /^"([^"]+)"/) {
                my $path = $1;
                my $alias = (split /::/, $path)[-1];
                $alias =~ s{.*/}{};
                push @imports, { alias => $alias, path => $path };
            }
        }
    }
    # single import
    while ($text =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        my $alias = $path;
        $alias =~ s{.*/}{};
        push @imports, { alias => $alias, path => $path };
    }
    while ($text =~ /import\s+(\w+)\s+"([^"]+)"/g) {
        push @imports, { alias => $1, path => $2 };
    }

    my %import_map;
    for my $imp (@imports) {
        $import_map{$imp->{alias}} = $imp->{path};
    }

    my @decls;
    my $line_num = 0;
    for my $line (split /\n/, $text) {
        $line_num++;
        next unless $line =~ /^func\s+/;
        if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)(?:\[[^\]]+\])?\s*\(/) {
            my ($recv, $name) = ($1, $2);
            my $recv_type;
            if (defined $recv && $recv ne '') {
                my @parts = split /\s+/, $recv;
                $recv_type = $parts[-1];
                $recv_type =~ s/^\*//;
            }
            push @decls, {
                line => $line_num,
                name => $name,
                recv_type => $recv_type,
                is_method => defined $recv && $recv ne '',
            };
        }
    }

    return {
        path => $path,
        pkg => $pkg,
        imports => \%import_map,
        decls => \@decls,
        text => $text,
        raw_lines => [split /\n/, $text],
    };
}

# Collect internal declarations
my %symbols;    # sym_id => info
my %decl_lines; # sym_id => set of "file:line"

find({
    wanted => sub {
        return unless /\.go$/;
        return unless $File::Find::name =~ m{/internal/};
        my $info = parse_go_file($File::Find::name);
        return unless $info->{pkg};

        my $dir = $File::Find::name;
        $dir =~ s{/[^/]+$}{};
        $dir =~ s{^\Q$REPO\E/?}{};
        $dir =~ s{^/}{};
        my $import_path = "github.com/usememos/memos/$dir";

        for my $d (@{$info->{decls}}) {
            my $sym_id = join '|', $import_path, ($d->{recv_type} // ''), $d->{name};
            $symbols{$sym_id} = {
                import_path => $import_path,
                pkg => $info->{pkg},
                dir => $dir,
                name => $d->{name},
                recv_type => $d->{recv_type},
                is_method => $d->{is_method},
                decl_file => $File::Find::name,
                decl_line => $d->{line},
            };
            $decl_lines{$sym_id}{$File::Find::name . ':' . $d->{line}} = 1;
        }
    },
    no_chdir => 1,
}, "$REPO/internal");

# Collect all go files
my @all_go_files;
find({
    wanted => sub {
        return unless /\.go$/;
        push @all_go_files, $File::Find::name;
    },
    no_chdir => 1,
}, $REPO);

# Build reverse map: import_path -> default alias candidates
my %path_to_pkgname;
for my $sym_id (keys %symbols) {
    my $s = $symbols{$sym_id};
    my $pkg = $s->{pkg};
    $path_to_pkgname{$s->{import_path}} = $pkg;
}

# Count call sites
my %call_sites;      # sym_id -> { "file:line" => 1 }
my %caller_files;    # sym_id -> { file => 1 }

for my $go_file (@all_go_files) {
    my $info = parse_go_file($go_file);
    next unless $info->{text};

    my $file_pkg = $info->{pkg};
    my %imports = %{$info->{imports}};

    # Also map default package name from import path
  my %alias_to_path = %imports;
    for my $alias (keys %imports) {
        $alias_to_path{$alias} = $imports{$alias};
    }

    my $line_num = 0;
    for my $line (@{$info->{raw_lines}}) {
        $line_num++;
        my $trim = $line;
        $trim =~ s/^\s+//;

        # Skip declarations
        next if $trim =~ /^func\s+/;
        next if $trim =~ /^type\s+/;
        next if $trim =~ /^var\s+/;
        next if $trim =~ /^const\s+/;

        # Qualified calls: alias.Name(
        while ($line =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($alias, $name) = ($1, $2);
            next if $alias eq 'http' || $alias eq 'json' || $alias eq 'fmt' || $alias eq 'strings' || $alias eq 'bytes' || $alias eq 'context' || $alias eq 'time' || $alias eq 'errors' || $alias eq 'log' || $alias eq 'slog' || $alias eq 'os' || $alias eq 'io' || $alias eq 'math' || $alias eq 'sort' || $alias eq 'strconv' || $alias eq 'regexp' || $alias eq 'sync' || $alias eq 'atomic' || $alias eq 'reflect' || $alias eq 'unsafe' || $alias eq 'unicode' || $alias eq 'filepath' || $alias eq 'path' || $alias eq 'net' || $alias eq 'url' || $alias eq 'template' || $alias eq 'html' || $alias eq 'crypto' || $alias eq 'encoding' || $alias eq 'database' || $alias eq 'sql' || $alias eq 'testing' || $alias eq 'assert' || $alias eq 'require';
            my $import_path = $alias_to_path{$alias};
            next unless defined $import_path;

            # Match package-level function
            my $sym_id = join '|', $import_path, '', $name;
            if (exists $symbols{$sym_id}) {
                my $site = "$go_file:$line_num";
                next if exists $decl_lines{$sym_id}{$site};
                $call_sites{$sym_id}{$site} = 1;
                $caller_files{$sym_id}{$go_file} = 1;
            }

            # Match method on exported type: alias is type name? No, alias is package.
            # Methods called as pkg.TypeMethod only if function value - rare.
        }

        # Method calls: recv.Method(
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($recv_var, $method) = ($1, $2);
            # Try to match methods in same file's package or any internal package with this method name
            # We need receiver type inference - hard. Match all methods with this name in current package dir if unqualified context
        }

        # Unqualified calls: Name(
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
            my ($name) = ($1);
            next if $name =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|copy|close|panic|recover|print|println|complex|real|imag|map|chan|struct|interface|select|case|default|range|break|continue|fallthrough|goto|else|switch)$/;

            # Same-package calls: find symbols in packages where this file belongs
            for my $sym_id (keys %symbols) {
                my $s = $symbols{$sym_id};
                next if $s->{is_method};  # skip methods for unqualified - need receiver
                next if $s->{name} ne $name;
                # file must be in same import path
                my $file_dir = $go_file;
                $file_dir =~ s{/[^/]+$}{};
                $file_dir =~ s{^\Q$REPO\E/?}{};
                $file_dir =~ s{^/}{};
                my $file_import = "github.com/usememos/memos/$file_dir";
                next unless $file_import eq $s->{import_path};

                my $site = "$go_file:$line_num";
                next if exists $decl_lines{$sym_id}{$site};
                $call_sites{$sym_id}{$site} = 1;
                $caller_files{$sym_id}{$go_file} = 1;
            }
        }

        # Method calls with common receiver patterns in same package
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($recv_var, $method) = ($1, $2);
            my $file_dir = $go_file;
            $file_dir =~ s{/[^/]+$}{};
            $file_dir =~ s{^\Q$REPO\E/?}{};
            $file_dir =~ s{^/}{};
            my $file_import = "github.com/usememos/memos/$file_dir";

            for my $sym_id (keys %symbols) {
                my $s = $symbols{$sym_id};
                next unless $s->{is_method};
                next unless $s->{name} eq $method;
                next unless $s->{import_path} eq $file_import;

                my $site = "$go_file:$line_num";
                next if exists $decl_lines{$sym_id}{$site};
                $call_sites{$sym_id}{$site} = 1;
                $caller_files{$sym_id}{$go_file} = 1;
            }
        }
    }
}

# Rank by call site count
my @ranked = sort {
    (scalar keys %{$call_sites{$b}}) <=> scalar keys %{$call_sites{$a}}
    || $a cmp $b
} keys %symbols;

print "TOP 40 by distinct call-site count:\n";
for my $i (0..39) {
    last unless $i < @ranked;
    my $id = $ranked[$i];
    my $s = $symbols{$id};
    my $sites = scalar keys %{$call_sites{$id} // {}};
    my $callers = scalar keys %{$caller_files{$id} // {}};
    my $label = $s->{is_method} ? "($s->{recv_type}).$s->{name}" : $s->{name};
    print sprintf("%4d sites, %3d caller-files | %s | %s | %s\n",
        $sites, $callers, $s->{import_path}, $label, $s->{decl_file});
}

print "\nTotal internal symbols: " . scalar(keys %symbols) . "\n";

