args.command:
# Full scan: all func decls in internal, count call sites with perl
perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";

sub strip { my ($t)=@_; $t=~s{/\*.*?\*/}{}gs; join("\n", map { s{//.*$}{}; $_ } split /\n/, $t) }

my @internal = split /\n/, `find $REPO/internal -name "*.go" -type f`;
my %decls; # symkey => {file,line,name,recv,path}
for my $f (@internal) {
  next unless $f;
  open my $fh,"<",$f or next; my $raw=do{local $/;<$fh>}; close $fh;
  my @lines = split /\n/, strip($raw);
  my $dir=$f; $dir=~s{/[^/]+$}{}; $dir=~s{^\Q$REPO\E/?}{};
  my $ip="github.com/usememos/memos/$dir";
  my $n=0;
  for (@lines) {
    $n++;
    next unless /^func\s+/;
    if (/^func\s+(?:\(([^)]+)\)\s+)?(\w+)/) {
      my ($recv,$name)=($1,$2);
      my $rt; if(defined $recv && $recv ne ""){ my @p=split /\s+/,$recv; $rt=$p[-1]; $rt=~s/^\*//; }
      my $key = "$ip|".($rt//"")."|$name";
      $decls{$key}={file=>$f,line=>$n,name=>$name,recv=>$rt,ip=>$ip};
    }
  }
}

# merge multiline text per file
my @all = split /\n/, `find $REPO -name "*.go" -type f`;
my %counts; my %sites; my %callers;
for my $f (@all) {
  next unless $f;
  open my $fh,"<",$f or next; my $raw=do{local $/;<$fh>}; close $fh;
  my $text = strip($raw);
  $text =~ s/\s+/ /g; # flatten for multiline calls

  my $dir=$f; $dir=~s{/[^/]+$}{}; $dir=~s{^\Q$REPO\E/?}{};
  my $file_ip="github.com/usememos/memos/$dir";

  # imports
  my %imp;
  while ($text =~ /import\s*\((.*?)\)/g) {
    for my $line (split / /, $1) {
      next unless $line =~ /"([^"]+)"/;
      my $p=$1; my $a=$p; $a=~s{.*/}{}; $imp{$a}=$p;
    }
  }
  while ($text =~ /import\s+(\w+)\s+"([^"]+)"/g) { $imp{$1}=$2 }
  while ($text =~ /import\s+"([^"]+)"/g) { my $p=$1; my $a=$p; $a=~s{.*/}{}; $imp{$a}=$p }

  for my $key (keys %decls) {
    my $d=$decls{$key};
    my ($ip,$rt,$name)=split /\|/,$key;
    my $pat;
    if ($rt eq "") {
      # package func: alias.name( or unqualified in same pkg
      my $q=0;
      for my $alias (keys %imp) {
        next unless $imp{$alias} eq $ip;
        my $re = qr/\b\Q$alias\E\.\Q$name\E\s*\(/;
        $q += () = $text =~ /$re/g;
      }
      if ($file_ip eq $ip) {
        $q += () = $text =~ /\b\Q$name\E\s*\(/g;
        # subtract declaration
        $q-- if $d->{file} eq $f; # approx
      }
      if ($q>0) { $counts{$key}+=$q; }
    } else {
      # method: recv.name( in same package files only (conservative)
      next unless $file_ip eq $ip;
      my $re = qr/\.\Q$name\E\s*\(/;
      my $q = () = $text =~ /$re/g;
      $q-- if $d->{file} eq $f;
      if ($q>0) { $counts{$key}+=$q; }
    }
  }
}

my @ranked = sort { $counts{$b} <=> $counts{$a} || $a cmp $b } keys %decls;
print "TOP 25 (flattened multiline, approximate):\n";
for my $i (0..24) {
