args.streamContent:
#!/usr/bin/env perl
use strict;
use warnings;

my $REPO = '/bench/repo';

sub strip_comments {
    my ($text) = @_;
    $text =~ s{/\*.*?\*/}{}gs;
    my @lines;
    for my $line (split /\n/, $text) {
        $line =~ s{//.*$}{};
        push @lines, $line;
    }
    return join("\n", @text);
}

sub strip_comments_lines {
    my ($text) = @_;
    $text =~ s{/\*.*?\*/}{}gs;
    return [map { s{//.*$}{}; $_ } split /\n/, $text];
}

sub file_import_path {
    my ($path) = @_;
    my $dir = $path;
    $dir =~ s{/[^/]+$}{};
    $dir =~ s{^\Q$REPO\E/?}{};
    $dir =~ s{^/}{};
    return "github.com/usememos/memos/$dir";
}

sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return;
    my $raw = do { local $/; <$fh> };
    close $fh;
    my $lines = strip_comments_lines($raw);
    my $text = join "\n", @$lines;

    my $pkg;
    if ($text =~ /^package\s+(\w+)/m) {
        $pkg = $1;
    }

    my %import_map;
    while ($text =~ /import\s*\((.*?)\)/gs) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/^\s+|\s+$//g;
            next if $line eq '' || $line =~ /^_/;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                $import_map{$1} = $2;
            } elsif ($line =~ /^"([^"]+)"/) {
                my $ip = $1;
                my $alias = $ip;
                $alias =~ s{.*/}{};
                $import_map{$alias} = $ip;
            }
        }
    }
    while ($text =~ /import\s+"([^"]+)"/g) {
        my $ip = $1;
        my $alias = $ip;
        $alias =~ s{.*/}{};
        $import_map{$alias} = $ip;
    }
    while ($text =~ /import\s+(\w+)\s+"([^"]+)"/g) {
        $import_map{$1} = $2;
    }

    my @decls;
    my $line_num = 0;
    for my $line (@$lines) {
        $line_num++;
        next unless $line =~ /^func\s+/;
        if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)(?:\[[^\]]+\])?\s*\(/) {
            my ($recv, $name) = ($1, $2);
            my $recv_type;
            if (defined $recv && $recv ne '') {
                my @parts = split /\s+/, $recv;
                $recv_type = $parts[-1];
                $recv_type =~ s/^\*//;
            }
            push @decls, {
                line => $line_num,
                name => $name,
                recv_type => $recv_type,
                is_method => defined $recv && $recv ne '',
            };
        }
    }

    return {
        path => $path,
        pkg => $pkg,
        imports => \%import_map,
        decls => \@decls,
        lines => $lines,
        import_path => file_import_path($path),
    };
}

my @internal_files = split /\n/, `find '$REPO/internal' -name '*.go' -type f 2>/dev/null`;
my @all_go_files = split /\n/, `find '$REPO' -name '*.go' -type f 2>/dev/null`;

my %symbols;
my %decl_lines;
my %name_to_symids;

for my $path (@internal_files) {
    next unless $path;
    my $info = parse_go_file($path);
    next unless $info && $info->{pkg};

    for my $d (@{$info->{decls}}) {
        my $sym_id = join '|', $info->{import_path}, ($d->{recv_type} // ''), $d->{name};
        $symbols{$sym_id} = {
            import_path => $info->{import_path},
            pkg => $info->{pkg},
            name => $d->{name},
            recv_type => $d->{recv_type},
            is_method => $d->{is_method},
            decl_file => $path,
            decl_line => $d->{line},
        };
        $decl_lines{$sym_id}{$path . ':' . $d->{line}} = 1;
        push @{$name_to_symids{$d->{name}}}, $sym_id;
    }
}

# Unique method/function names across internal (for cross-package method attribution)
my %unique_name;
for my $name (keys %name_to_symids) {
    $unique_name{$name} = 1 if @{$name_to_symids{$name}} == 1;
}

my %call_sites;
my %caller_files;

my %stdlib = map { $_ => 1 } qw(
    http json fmt strings bytes context time errors log slog os io math sort strconv regexp
    sync atomic reflect unsafe unicode filepath path net url template html crypto encoding
    database sql testing assert require slices cmp iter cel jwt
);

# Join multiline calls: if line ends with comma or unfinished paren, merge next line
sub join_logical_lines {
    my ($lines) = @_;
    my @joined;
    my $buf = '';
    my @start_lines;
    my $start = 1;
    for my $i (0 .. $#$lines) {
        my $line = $lines->[$i];
        if ($buf eq '') { $start = $i + 1; }
        $buf .= ' ' . $line;
        # heuristic: continue if unbalanced parens or line ends with , or (
        my $open = ($buf =~ tr/\(//);
        my $close = ($buf =~ tr/\)//);
        if ($open > $close || $buf =~ /,\s*$/) {
            next;
        }
        push @joined, { text => $buf, line => $start };
        $buf = '';
    }
    push @joined, { text => $buf, line => $start } if $buf ne '';
    return \@joined;
}

for my $go_file (@all_go_files) {
    next unless $go_file;
    my $info = parse_go_file($go_file);
    next unless $info && $info->{lines};

    my %imports = %{$info->{imports}};
    my $file_import = $info->{import_path};
    my $joined = join_logical_lines($info->{lines});

    for my $jl (@$joined) {
        my $line = $jl->{text};
        my $line_num = $jl->{line};
        my $trim = $line;
        $trim =~ s/^\s+//;
        next if $trim =~ /^func\s+/;
        next if $trim =~ /^type\s+\w+\s+(?:struct|interface)/;

        # Qualified package-level calls
        while ($line =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($alias, $name) = ($1, $2);
            next if $stdlib{$alias};
            my $import_path = $imports{$alias};
            if (defined $import_path) {
                my $sym_id = join '|', $import_path, '', $name;
                if (exists $symbols{$sym_id}) {
                    my $site = "$go_file:$line_num";
                    next if exists $decl_lines{$sym_id}{$site};
                    $call_sites{$sym_id}{$site} = 1;
                    $caller_files{$sym_id}{$go_file} = 1;
                }
            }

            # Cross-package method calls for globally unique method names
            if ($unique_name{$name}) {
                my $sym_id = $name_to_symids{$name}[0];
                my $s = $symbols{$sym_id};
                if ($s->{is_method}) {
                    my $site = "$go_file:$line_num";
                    next if exists $decl_lines{$sym_id}{$site};
                    $call_sites{$sym_id}{$site} = 1;
                    $caller_files{$sym_id}{$go_file} = 1;
                }
            }
        }

        # Unqualified package-level calls (same package only)
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
            my ($name) = ($1);
            next if $name =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|copy|close|panic|recover|print|println|complex|real|imag|map|chan|struct|interface|select|case|default|range|break|continue|fallthrough|goto|else)$/;

            my $sym_id = join '|', $file_import, '', $name;
            if (exists $symbols{$sym_id} && !$symbols{$sym_id}{is_method}) {
                my $site = "$go_file:$line_num";
                next if exists $decl_lines{$sym_id}{$site};
                $call_sites{$sym_id}{$site} = 1;
                $caller_files{$sym_id}{$go_file} = 1;
            }
        }

        # Same-package method calls (recv.Method) - attribute to all methods with that name in package
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($recv_var, $method) = ($1, $2);
            for my $sym_id (@{$name_to_symids{$method} // []}) {
                my $s = $symbols{$sym_id};
                next unless $s->{is_method};
                next unless $s->{import_path} eq $file_import;

                my $site = "$go_file:$line_num";
                next if exists $decl_lines{$sym_id}{$site};
                $call_sites{$sym_id}{$site} = 1;
                $caller_files{$sym_id}{$go_file} = 1;
            }
        }
    }
}

my @ranked = sort {
    (scalar keys %{$call_sites{$b} // {}}) <=> scalar keys %{$call_sites{$a} // {}}
    || $a cmp $b
} keys %symbols;

print "TOP 30 by distinct call-site count:\n";
for my $i (0..29) {
    last unless $i < @ranked;
    my $id = $ranked[$i];
    my $s = $symbols{$id};
    my $sites = scalar keys %{$call_sites{$id} // {}};
    my $callers = scalar keys %{$caller_files{$id} // {}};
    my $label = $s->{is_method} ? "($s->{recv_type}).$s->{name}" : $s->{name};
    print sprintf("%4d sites, %3d caller-files | %s | %s | %s:%d\n",
        $sites, $callers, $s->{import_path}, $label, $s->{decl_file}, $s->{decl_line});
}

# Show ties at max
my $max = scalar keys %{$call_sites{$ranked[0]} // {}};
print "\nAll symbols tied at max ($max):\n";
for my $id (@ranked) {
    my $sites = scalar keys %{$call_sites{$id} // {}};
    last if $sites < $max;
    my $s = $symbols{$id};
    my $label = $s->{is_method} ? "($s->{recv_type}).$s->{name}" : $s->{name};
    print "  $label ($sites sites)\n";
}

