use strict; use warnings;
my $REPO="/bench/repo";
my @files = split /\n/, `find $REPO/internal -name "*.go"`;
my %decls; # name => [{recv,file,line}]
for my $f (@files) {
  open F,"<",$f or next; my $t=do{local $/;<F>}; close F;
  $t=~s{/\*.*?\*/}{}gs; $t=~s{//.*$}{}gm;
  while ($t =~ /^func\s+\(([^)]+)\)\s+(\w+)/gm) {
    push @{$decls{$2}}, {recv=>$1,file=>$f};
  }
}
my @all = split /\n/, `find $REPO -name "*.go"`;
for my $name (sort { ($decls{$b}?scalar(@{$decls{$b}}):0) <=> ($decls{$a}?scalar(@{$decls{$a}}):0) } keys %decls) {
