use strict; use warnings;
my $REPO="/bench/repo";

sub strip { my($t)=@_; $t=~s{/\*.*?\*/}{}gs; join("\n", map { s{//.*$}{}; $_ } split /\n/, $t) }
sub ipath { my($f)=@_; $f=~s{/[^/]+$}{}; $f=~s{^\Q$REPO\E/?}{}; "github.com/usememos/memos/$f" }

my @internal = split /\n/, `find $REPO/internal -name "*.go"`;
my %sym; my %decl_line;
for my $f (@internal) {
