my %sites; my %cfiles;
my %stdlib = map{$_=>1} qw(http json fmt strings bytes context time errors log os io math sort strconv regexp sync reflect unicode filepath net url template html crypto encoding database sql testing cel jwt);

for my $f (@all) {
  open F,"<",$f or next; my @raw=split /\n/, do{local $/;<F>}; close F;
  my $ip=ipath($f);
