    return unless $buf ne "";
    my $trim=$buf; $trim=~s/^\s+//;
    return if $trim =~ /^func\s+/;
    # qualified
    while ($buf =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
      my($a,$n)=($1,$2); next if $stdlib{$a};
      my $pip=$imp->{$a}; next unless $pip;
      my $id="$pip||$n";
      if (exists $sym{$id} && !$sym{$id}{method}) {
        my $site="$f:$start"; next if $decl_line{$site};
        $sites{$id}{$site}=1; $cfiles{$id}{$f}=1;
      }
    }
    # unqualified pkg func same package
    while ($buf =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
      my $n=$1; next if $n=~/^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|copy|close|panic|recover)$/;
      my $id="$ip||$n";
      if (exists $sym{$id} && !$sym{$id}{method}) {
        my $site="$f:$start"; next if $decl_line{$site};
        $sites{$id}{$site}=1; $cfiles{$id}{$f}=1;
      }
    }
    # same-package methods recv.method
    while ($buf =~ /(?:^|[^\w.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
      my $m=$2;
      for my $id (keys %sym) {
        next unless $sym{$id}{method} && $sym{$id}{name} eq $m && $sym{$id}{ip} eq $ip;
        my $site="$f:$start"; next if $decl_line{$site};
        $sites{$id}{$site}=1; $cfiles{$id}{$f}=1;
      }
    }
  }
  for my $line (@raw) {
    $ln++; $line=~s{//.*$}{};
    if ($buf eq "") { $start=$ln; }
    $buf .= " $line";
    my $open=($buf=~tr/\(//); my $close=($buf=~tr/\)//);
    if ($open>$close || $buf=~/,\s*$/) { next; }
    flush($f,$ip,$buf,$start,\%imp); $buf="";
  }
  flush($f,$ip,$buf,$start,\%imp) if $buf ne "";
}

# cross-package unique method names: only if exactly one method decl in internal with that name
my %meth_names;
for my $id (keys %sym) { push @{$meth_names{$sym{$id}{name}}}, $id if $sym{$id}{method}; }
for my $f (@all) {
  open F,"<",$f or next; my @raw=split /\n/, do{local $/;<F>}; close F;
  my $ln=0; my $buf=""; my $start=1;
  for my $line (@raw) {
    $ln++; $line=~s{//.*$}{};
    if ($buf eq "") { $start=$ln; }
    $buf .= " $line";
    my $open=($buf=~tr/\(//); my $close=($buf=~tr/\)//);
    if ($open>$close || $buf=~/,\s*$/) { next; }
    while ($buf =~ /\.([A-Za-z_]\w*)\s*\(/g) {
      my $m=$1;
      next unless @{$meth_names{$m}//[]} == 1;
      # exclude sort.Interface standard methods and very common
      next if $m =~ /^(Len|Less|Swap|String|Error|ServeHTTP|Read|Write|Close|Flush|Header|Next|Field|Compile)$/;
      my $id=$meth_names{$m}[0];
      my $site="$f:$start"; next if $decl_line{$site};
      $sites{$id}{$site}=1; $cfiles{$id}{$f}=1;
    }
    $buf="";
  }
}

my @ranked = sort { scalar(keys%{$sites{$b}//{}}) <=> scalar(keys%{$sites{$a}//{}}) } keys %sym;
print "TOP 20 conservative+cross-package unique methods:\n";
for (0..19) {
  my $id=$ranked[$_]; my $s=$sym{$id};
  my $n=scalar keys %{$sites{$id}//{}};
  my $cf=scalar keys %{$cfiles{$id}//{}};
  my $label=$s->{method}?"($s->{rt}).$s->{name}":$s->{name};
  print "$n sites, $cf files | $label | $s->{file}:$s->{line}\n";
}
print "\nTies at max:\n";
my $max=scalar keys %{$sites{$ranked[0]}//{}};
for my $id (@ranked) { my $n=scalar keys %{$sites{$id}//{}}; last if $n<$max; my $s=$sym{$id}; print "  $s->{name} ($n)\n"; }
'

