  while ($t =~ /import\s*\((.*?)\)/gs) {
    for (split /\n/,$1) {
      s/^\s+|\s+$//g;
      if (/^(\w+)\s+"([^"]+)"/) { $imp{$1}=$2 }
      elsif (/^"([^"]+)"/) { my $p=$1; my $a=$p; $a=~s{.*/}{}; $imp{$a}=$p }
    }
  }
  while ($t =~ /import\s+(\w+)\s+"([^"]+)"/g) { $imp{$1}=$2 }
